INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(115746, 'ruRU', '', 'А до тех пор, смотри, куда ступаешь. Город в полной боевой готовности, и стража убьёт тебя на месте.', 24330),
(115776, 'ruRU', '', 'Мои лучники держат луки натянутыми, готовые подстрелить любого демона, что посмеет войти за эти стены.', 24330),
(115777, 'ruRU', '', 'Это работает?', 24330),
(115779, 'ruRU', '', 'Запусти сигнальную ракету, и мы увидим.', 24330),
(115782, 'ruRU', '', 'Я узнаю, не видели ли чего-нибудь Земляные в Каменном Очаге.', 24330),
(115785, 'ruRU', '', 'Демоны рядом! Часовые, готовьте клинки!', 24330),
(115786, 'ruRU', '', 'У меня для тебя предложение. Прямо под нами лежит превосходное крабовое мясо... то есть они пока ещё живые, но ты понимаешь, о чём я.$b$bУ меня тут есть буйки, которые ты можешь использовать, чтобы поднять их на поверхность. Ты спускаешься и прикрепляешь буйки, а я поймаю всё, что поднимется наверх.$b$bСделай это для меня, и я обещаю щедрую награду. Что скажешь?', 24330),
(115788, 'ruRU', '', 'Будь осторожен там, внизу. Рядом с крабами обитают и другие создания, с которыми тебе лучше не пересекаться.$b$bЗнаешь, я мог бы стать $c вроде тебя, если бы не пошёл по стопам отца и не отправился в море.', 24330),
(115789, 'ruRU', '', 'Предки... простите меня...', 24330),
(115792, 'ruRU', '', 'Ты слишком остро реагируешь, Террат. Ответы придут. Ах, смертный приближается. Там, где беда, плоть никогда далеко, хм?', 24330),
(115793, 'ruRU', '', 'Что-то приводит троггов в исступление. Возможно, это связано с твоим пропавшим молотом. Будь так добр, разберись с ними, хм?', 24330),
(115794, 'ruRU', '', 'Ох, как чудесно, чудесно! Выводок в безопасности. Вернись ко мне, к моему трону. Я знаю, где искать твой молот — и каменные драконы теперь свободны помочь.', 24330),
(115795, 'ruRU', '', 'А вот и мой новый любимый плотничек. Ты истинный друг Матери Камня, шаман.', 24330),
(115796, 'ruRU', '', 'Вождь троггов знает, где упал твой молот, шаман. Выбей из него эти сведения! Каменные драконы в твоём распоряжении.', 24330),
(115797, 'ruRU', '', 'Это должно помочь тебе передвигаться там, внизу. Действует недолго, так что поспеши.', 24330),
(115803, 'ruRU', '', 'Проблемам с поверхности не место здесь, внизу, шаман. Надеюсь, ты намерен всё исправить.', 24330),
(115824, 'ruRU', '', 'Вередис... нет!', 24330),
(115828, 'ruRU', '', 'Я же сказал — никаких выстрелов в упор!', 24330),
(115833, 'ruRU', '', 'Ты выиграл мне достаточно времени. Отвар готов!', 24330),
(115838, 'ruRU', '', 'Благодарю, $n. Я тебя не разочарую.', 24330),
(115840, 'ruRU', '', 'Думаешь, это глупое зелье тебя спасёт? Выходи и встреться со мной лицом к лицу. Я уничтожу всё, что осталось от Разрушенного храма!', 24330),
(115841, 'ruRU', '', 'Довольно. Твоё время окончено, монах!', 24330),
(115842, 'ruRU', '', 'Скажи тому, кого ты пошлёшь, что чем скорее у Гардуна будут его демонические игрушки, тем скорее у нас будут новые воины Ясеневых Языков.', 24330),
(115843, 'ruRU', '', 'Эй, Гардун, новые воины уже готовы?', 24330),
(115844, 'ruRU', '', 'Неужели это действительно Лорамус Талипедес? И если это он, спасать нам его или убивать?', 24330),
(115845, 'ruRU', '', 'Будь осторожен, $n. Он там, внизу, частенько угрожает нам на демоническом языке.', 24330),
(115849, 'ruRU', '', 'Что тебя так задержало? Я должен был стать твоим первым защитником.', 24330),
(115870, 'ruRU', '', 'Три сестры мои на древе том повисли,\nВ преступлениях тех не было и мысли,\nМладшая сестра одна сумела убежать,\nКогда петля на шею стала одевать,\nСтарый Воронья Вершина — вот кто виноват,\nСними сие проклятье, смой наш срам.', 24330),
(115877, 'ruRU', '', 'Проклятье снято. Теперь я наконец могу покоиться. Но помни, герой. Не дай добрым людям смириться с несправедливостью.', 24330),
(115890, 'ruRU', '', 'Герои, ваш бой — с Коритисом. Я защищу вас от его крылатого чудовища.', 24330),
(115905, 'ruRU', '', 'Ты хорошо научился сражаться с этими существами, но это лишь одна из многих битв.', 24330),
(115906, 'ruRU', '', 'Это Фу Цзань. Возьми его. Пусть он защитит тебя в грядущие тёмные времена.', 24330),
(115907, 'ruRU', '', 'Поспеши, охотник на демонов. Мне не нравится вид того костра там.', 24330),
(115909, 'ruRU', '', 'Да, Великий мастер здесь! Теперь у этих демонов нет ни шанса!', 24330),
(115913, 'ruRU', '', 'Для меня всегда было честью быть одним из Служителей Иллидана. Но официально стать одним из иллидари... отвернись, $n, кажется, я могу заплакать.', 24330),
(115914, 'ruRU', '', 'Позволь уверить тебя, $n, я использую всё, что есть в моём распоряжении, всю силу Косы Душ, чтобы выяснить, где находятся Кария и Вередис.', 24330),
(115928, 'ruRU', '', 'Коса Душ говорит мне, что она ревнует к тебе за то, что ты собираешь столько могущественных духов.', 24330),
(115934, 'ruRU', '', 'Жалкие создания! Вы уже украли мою жизнь! Что ещё вы хотите у меня забрать?', 24330),
(115935, 'ruRU', '', 'Мы прошли через столько всего вместе. Разумеется, я согласен!', 24330),
(115957, 'ruRU', '', 'Хранилище изобилует магическими защитными механизмами. Один из них можно найти в тюрьме, построенной для демона Глейзера.', 24330);
